{
  "findings": [
    {
      "check_id": "CKV_AWS_16",
      "title": "Ensure all data stored in the RDS is securely encrypted at rest",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have encryption enabled, which could lead to sensitive data being exposed if the storage is compromised."
    },
    {
      "check_id": "CKV_AWS_129",
      "title": "Ensure that respective logs of Amazon Relational Database Service (Amazon RDS) are enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Logging is not enabled for the RDS instance, which could hinder troubleshooting and security auditing."
    },
    {
      "check_id": "CKV_AWS_226",
      "title": "Ensure DB instance gets all minor upgrades automatically",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Automatic minor version upgrades are not enabled, which could leave the database vulnerable to known issues in outdated versions."
    },
    {
      "check_id": "CKV_AWS_118",
      "title": "Ensure that enhanced monitoring is enabled for Amazon RDS instances",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Enhanced monitoring is not enabled, which limits visibility into database performance and potential issues."
    },
    {
      "check_id": "CKV_AWS_293",
      "title": "Ensure that AWS database instances have deletion protection enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Deletion protection is not enabled, which increases the risk of accidental or malicious deletion of the database."
    },
    {
      "check_id": "CKV_AWS_353",
      "title": "Ensure that RDS instances have performance insights enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Performance insights are not enabled, which limits the ability to analyze and optimize database performance."
    },
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Multi-AZ is not enabled, which reduces the availability and fault tolerance of the database."
    },
    {
      "check_id": "CKV2_AWS_60",
      "title": "Ensure RDS instance with copy tags to snapshots is enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Copying tags to snapshots is not enabled, which could lead to inconsistent tagging and difficulty in managing resources."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n  storage_encrypted = true\n  auto_minor_version_upgrade = true\n  monitoring_interval = 60\n  deletion_protection = true\n  performance_insights_enabled = true\n  copy_tags_to_snapshot = true\n  enabled_cloudwatch_logs_exports = [\"error\", \"general\", \"slowquery\", \"audit\"]\n}",
  "fix_summary": "Enabled encryption at rest, logging, automatic minor version upgrades, enhanced monitoring, deletion protection, performance insights, Multi-AZ, and copying tags to snapshots for the RDS instance."
}
